package org.example.api.returns;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.*;import org.example.config.ConfigManager;import java.io.IOException;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;
public final class ReturnApiClient{
 private final HttpClient http = org.example.api.ApiRuntime.HTTP;
 private final ObjectMapper json = org.example.api.ApiRuntime.JSON;private final String base;
 public ReturnApiClient(){String b=ConfigManager.getDataApiBaseUrl();while(b.endsWith("/"))b=b.substring(0,b.length()-1);base=b;}
 public List<Summary> list(String type){return get("/api/returns?type="+enc(type),new TypeReference<List<Summary>>(){});}public Page page(String type,int page,int size,String q,String party,String status,String from,String to){return get("/api/returns/page?type="+enc(type)+"&page="+Math.max(0,page)+"&size="+Math.max(10,Math.min(size,200))+"&q="+enc(q)+"&party="+enc(party)+"&status="+enc(status)+"&from="+enc(from)+"&to="+enc(to),Page.class);}public List<Summary> allFiltered(String type,String q,String party,String status,String from,String to){Page first=page(type,0,200,q,party,status,from,to);List<Summary> out=new ArrayList<>(first.rows()==null?List.of():first.rows());for(int p=1;p<first.totalPages();p++){Page next=page(type,p,200,q,party,status,from,to);if(next.rows()!=null)out.addAll(next.rows());}return out;}public Map<String,Double> returned(String type,String invoice){return get("/api/returns/returned?type="+enc(type)+"&invoice="+enc(invoice),new TypeReference<Map<String,Double>>(){});}public String create(CreateRequest d){return post("/api/returns",d,Created.class).returnNo();}public Details details(String no){return get("/api/returns/"+encPath(no),Details.class);}public void update(String no,String field,String value){put("/api/returns/"+encPath(no),new UpdateRequest(field,value),Ok.class);}public void refund(String no,double a){post("/api/returns/"+encPath(no)+"/refund",new RefundRequest(a),Ok.class);}public List<RefundRow> refunds(String no){return get("/api/returns/"+encPath(no)+"/refunds",new TypeReference<List<RefundRow>>(){});}public int recordRefund(String no,RefundCreateRequest d){return post("/api/returns/"+encPath(no)+"/refunds",d,RefundCreated.class).id();}public void cancel(String no,boolean sales){postNoBody("/api/returns/"+encPath(no)+"/cancel?sales="+sales);}public void delete(String no,boolean sales){delete("/api/returns/"+encPath(no)+"?sales="+sales);}
 private <T>T get(String p,Class<T>c){return req("GET",p,null,c,null);}private <T>T get(String p,TypeReference<T>t){return req("GET",p,null,null,t);}private <T>T post(String p,Object b,Class<T>c){return req("POST",p,b,c,null);}private <T>T put(String p,Object b,Class<T>c){return req("PUT",p,b,c,null);}private void postNoBody(String p){req("POST",p,null,Ok.class,null);}private void delete(String p){req("DELETE",p,null,Ok.class,null);}private <T>T req(String m,String p,Object b,Class<T>c,TypeReference<T>t){try{HttpRequest.Builder q=HttpRequest.newBuilder(URI.create(base+p)).timeout(Duration.ofSeconds(30)).header("Accept","application/json");org.example.api.ApiSession.authorize(q);if(b!=null)q.header("Content-Type","application/json").method(m,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(b)));else q.method(m,HttpRequest.BodyPublishers.noBody());var r=http.send(q.build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()<200||r.statusCode()>=300)throw new IllegalStateException("Return API error ("+r.statusCode()+"): "+r.body());return t!=null?json.readValue(r.body(),t):json.readValue(r.body(),c);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}catch(IOException e){throw new IllegalStateException("Cannot reach return API at "+base,e);}}private String enc(String s){return URLEncoder.encode(s==null?"":s,StandardCharsets.UTF_8);}private String encPath(String s){return enc(s).replace("+","%20");}
 public record Summary(String no,String date,String invoice,String party,double total,double refund,String reason,String status,String refundStatus,String email){}public record Line(String name,String code,double quantity,String unit,double rate,double tax,double amount,String reason){}public record Details(String no,String date,String invoice,String party,String type,String paymentTerms,String currency,String createdAt,String updatedAt,String attachment,String notes,double total,double refund,String status,String refundStatus,List<Line> lines){}public record CreateLine(String code,double quantity,double amount,String reason){}public record CreateRequest(String type,String invoiceNo,int partyId,String returnDate,List<CreateLine> lines){}public record Created(String returnNo){}public record UpdateRequest(String field,String value){}public record RefundRequest(double amount){}public record RefundCreateRequest(String date,double amount,String mode,String reference,String bankAccount,String refundedParty,String notes,String refundType,String createdBy){}public record RefundRow(int id,String date,String reference,String mode,String bankAccount,double amount,String refundedParty,String status,String notes,String attachment,String refundType){}public record RefundCreated(int id){}public record Metrics(double total,long count,double monthAmount,long monthCount,double approvedAmount,double refundAmount,double average){}public record Page(List<Summary> rows,int page,int size,long totalRows,int totalPages,Metrics metrics,List<String> parties){}public record Ok(boolean success,String message){}
}
